def safety_check(self):
        """Implement the `safety_check` function."""
        # Short-circuit if user didn't give any expectations; otherwise our
        # assumptions below will be inaccurately violated and explode.
        if not self.guard_only:
            raise ValueError("At least one expectation must be provided.")

def safety_check(self):
        """
        Implement the `safety_check` function.
        """
        # Short-circuit if user didn't give any expectations; otherwise our
        # assumptions below will be inaccurately violated and explode.
        if not self.commands and not self.cmd and not self.transfers:
            raise ValueError(
                "You must provide at least one command or transfer expectation."
            )

def safety_check(self):
        """Implement the `safety_check` function."""
        if not self.guard_only:
